{
  "controlWidth" : 12,
  "label" : "SEPeriodoTasa",
  "validationRequired" : "Step",
  "elementErrorMap" : {
    "FSC_PeriodoTasa__c" : "El período de tasa debe ser menor o igual al plazo en meses."
  },
  "showPersistentComponent" : [ true, false ],
  "show" : {
    "group" : {
      "operator" : "AND",
      "rules" : [ {
        "data" : "%PasoSolicitud:FSC_PlazoMeses__c%",
        "condition" : ">",
        "field" : "PasoSolicitud:FSC_PeriodoTasa__c"
      } ]
    }
  },
  "HTMLTemplateId" : "",
  "wpm" : false,
  "ssm" : false,
  "message" : { },
  "pubsub" : false
}

{
